# Waving Task Logic Node & Trajectory Execution
class SawyerWavingNode:
    def on_wave_triggered(self, msg):
        self.limb.move_to_neutral()
        for cycle in range(5):
            self.execute_waypoint_sweep("left", duration=0.8)
            self.execute_waypoint_sweep("right", duration=0.8)
        self.limb.move_to_neutral()

